package Day4;

public class ifelseif2condition {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
//largest of 3 number
		int a=10, b=20, c=30;
		if(a>b&&a>c)
		{
			System.out.println("A is largest");
		}
		else if(b>a&&b>c)
		{
			System.out.println("B is largest");
		}
		else
		{
			System.out.println("C is greater");
		}
	}

}
